package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceDocumentController;import com.rpb.reservation.workforce.documents.*;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.walkin.auth.LocalRuntimeSecurityConfiguration;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.TestPropertySource;import org.springframework.test.web.servlet.MockMvc;import org.springframework.mock.web.MockMultipartFile;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
@WebMvcTest(WorkforceDocumentController.class) @Import({LocalRuntimeSecurityConfiguration.class,com.rpb.reservation.appgate.api.AppGateApiErrorMapper.class}) @ActiveProfiles("local") @TestPropertySource(properties="rpb.local-auth.enabled=true")
class WorkforceDocumentLocalRuntimeSecurityTest {
 @Autowired MockMvc mvc;@MockBean CurrentActorProvider actors;@MockBean EmployeeDocumentService service;@MockBean com.rpb.reservation.appgate.application.AppGateService gate;@MockBean com.rpb.reservation.appgate.application.AppGateDenialAuditService denialAudit;
 @Test void onlyExactPrivateReadAndProtectedPutRoutesReachScopedService()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));String base="/api/v1/stores/"+UUID.randomUUID()+"/workforce",documents=base+"/employees/"+UUID.randomUUID()+"/documents",file=documents+"/"+UUID.randomUUID()+"/attachments/"+UUID.randomUUID();mvc.perform(get(base+"/document-types")).andExpect(status().isOk());mvc.perform(get(documents)).andExpect(status().isOk());mvc.perform(put(documents+"/"+UUID.randomUUID()).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isOk());mvc.perform(multipart(file).file(new MockMultipartFile("file","test.pdf","application/pdf","%PDF-1.7".getBytes())).param("expectedVersion","1").header("X-RPB-Workforce","1").with(r->{r.setMethod("PUT");return r;})).andExpect(status().isOk());verify(service).upload(any(),any(),any(),any(),any(),eq(1L),eq("test.pdf"),any());mvc.perform(delete(file)).andExpect(status().isForbidden());mvc.perform(post(documents)).andExpect(status().isForbidden());}
}
